const api=new URLSearchParams(location.search).get("apiBaseUrl"),$=(s)=>document.querySelector(s);let data;
async function request(route,options){const response=await fetch(new URL(route,api),options);if(!response.ok)throw new Error(`插件 API 返回 ${response.status}`);return response.json()}
function compact(number){return new Intl.NumberFormat("zh-CN",{notation:"compact",maximumFractionDigits:1}).format(number)}
function row(repo){const li=document.createElement("li");li.className=`repo-row${repo.read?" is-read":""}`;li.onclick=async()=>{window.open(repo.url,"_blank","noopener");data=await request(`read?id=${encodeURIComponent(repo.id)}`,{method:"POST"});render(data)};const rank=document.createElement("span");rank.className="rank";rank.textContent=repo.rank;const content=document.createElement("div");const name=document.createElement("h2");name.textContent=`${repo.owner} / ${repo.name}`;const description=document.createElement("p");description.textContent=repo.description||"暂无描述";const meta=document.createElement("div");meta.className="metadata";if(repo.language){const dot=document.createElement("i");dot.style.backgroundColor=repo.languageColor||"#8b949e";meta.append(dot,repo.language)}const metrics=document.createElement("span");metrics.textContent=`★ ${compact(repo.stars)}   分支 ${compact(repo.forks)}`;meta.append(metrics);const gained=document.createElement("strong");gained.textContent=`+${compact(repo.starsGained)} 星`;content.append(name,description,meta);li.append(rank,content,gained);return li}
function render(next){data=next;const repos=next.repositories??[];$("#repo-list").replaceChildren(...repos.map(row));$("#repo-list").hidden=!repos.length;$("#empty").hidden=!!repos.length;$("#warning").hidden=!next.lastError;const date=next.lastSuccessfulRefresh&&new Date(next.lastSuccessfulRefresh);$("#refresh-time").textContent=date?`上次刷新 ${new Intl.DateTimeFormat("zh-CN",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit"}).format(date)}`:"尚未刷新";$("#period").value=next.view.period;$("#language").value=next.view.language;$("#refresh").disabled=next.settings.policy==="disabled"}
async function refresh(){const b=$("#refresh");b.disabled=true;b.classList.add("spinning");$("#refresh-time").textContent="正在刷新...";try{await request("refresh",{method:"POST"});render(await request("summary"))}catch(error){const latest=await request("summary").catch(()=>data);render({...latest,lastError:latest?.lastError??error.message})}finally{b.classList.remove("spinning");b.disabled=data?.settings.policy==="disabled"}}
async function viewChanged(){data=await request(`view?period=${encodeURIComponent($("#period").value)}&language=${encodeURIComponent($("#language").value)}`,{method:"POST"});render(data)}
function showSettings(show){$("#sheet").hidden=!show;$("#scrim").hidden=!show;if(show){const s=data.settings;document.querySelector(`[name=policy][value=${s.policy}]`).checked=true;$("#interval").value=s.intervalMinutes;$("#interval").disabled=s.policy!=="fixed";$("#sheet input:checked").focus()}else $("#settings").focus()}
$("#refresh").onclick=$("#retry").onclick=$("#empty-refresh").onclick=refresh;$("#period").onchange=$("#language").onchange=viewChanged;$("#settings").onclick=()=>showSettings(true);$("#close-settings").onclick=$("#cancel-settings").onclick=$("#scrim").onclick=()=>showSettings(false);document.querySelectorAll("[name=policy]").forEach(r=>r.onchange=()=>$("#interval").disabled=r.value!=="fixed");$("#settings-form").onsubmit=async(e)=>{e.preventDefault();const f=new FormData(e.currentTarget);await request(`settings?policy=${f.get("policy")}&intervalMinutes=${f.get("intervalMinutes")}`,{method:"POST"});render(await request("summary"));showSettings(false)};addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#sheet").hidden)showSettings(false)});request("summary").then(render).catch(e=>$("#repo-list").innerHTML=`<li class="loading">${e.message}</li>`);
